{
  "name": "手掌",
  "description": "最常见的惩戒调教手段。",
  "attributes": {
    "power_value": "1-3(当[臀部状态]>200，该值变为0)",
    "special_effects": [
      "热臀效果",
      "羞耻感加倍"
    ],
    "tactile_sensation": "痛感温热，由表及里。轻则如暖流拂过，重则似热铁加身。掌击之下，臀肉颤动如水波。",
    "sound": "声响清脆，因力度而异。轻拍声声入耳，重掴则“啪”然作响，回荡于室内。",
    "application": "无所不适。既可用于长辈对晚辈的警示，亦可为正式施刑前的“热臀”，为后续惩罚做准备。"
  }
}

{
  "name": "戒尺",
  "description": "木材打磨制成，最常见的惩戒器具之一。",
  "attributes": {
    "power_value": "3-5",
    "special_effects": [
      "楞痕",
      "尖锐灼痛"
    ],
    "tactile_sensation": "痛感集中而深刻。",
    "sound": "“啪”或“咻”的一声，短促而凌厉，带着风声。",
    "application": "适用于女子犯错规训等需要留下明确惩戒痕迹的场合。"
  }
}

{
  "name": "藤条",
  "description": "取上好白藤，浸油晾晒而成，有各种粗细。",
  "attributes": {
    "power_value": "8-12",
    "special_effects": [
      "鞭痕",
      "剧痛",
      "平行排布",
      "红肿楞痕"
    ],
    "tactile_sensation": "痛感迅猛，触感集中。",
    "sound": "“咻—啪！”破空之声尖利，落肉之声清脆。",
    "application": "用于严厉的惩罚，并留下难以消退的痕迹，呈现平行排布微微隆起的红肿楞痕。"
  }
}

{
  "name": "绣花鞋底",
  "description": "取女子常着之绣花鞋，以其千层底击打。",
  "attributes": {
    "power_value": "2-4",
    "special_effects": [
      "强烈羞辱",
      "摩擦灼热"
    ],
    "tactile_sensation": "痛感驳杂，软底与硬底有不同触感。",
    "sound": "“噼啪”作响，声音散乱，略显沉闷。",
    "application": "适用于即兴的、以羞辱为主的薄惩，物理伤害不大，但心理效果显著。"
  }
}

{
  "name": "女板",
  "description": "专为训诫女子而制，多由梨木或楠竹打磨而成，比之家法板更为轻薄小巧，便于女子执掌。乃是内宅之中，纠正仪态、惩戒过错最常用的器具，亦可用于夫妻责臀的闺房情趣。",
  "attributes": {
    "power_value": "4-6",
    "special_effects": [
      "圆印",
      "板花",
      "大面积灼痛",
      "节奏感"
    ],
    "tactile_sensation": "痛感清脆而响亮，是介于戒尺的尖锐和家法板的沉闷之间的、大面积的灼痛。",
    "sound": "“啪！啪！”声音清亮悦耳，极富节奏感，能穿透门扉，清晰宣告着规矩的执行。",
    "application": "内宅训诫首选，效果显著且稳定，可使受罚者出声求饶，亦可使其情迷其中，出声求责。"
  }
}

{
  "name": "革带",
  "description": "男子腰间所束的牛皮或犀皮腰带。",
  "attributes": {
    "power_value": "6-8 (单层), 8-10 (折叠)",
    "special_effects": [
      "声音清脆",
      "皮革包裹感",
      "复合痛感"
    ],
    "tactile_sensation": "疼痛是复合型的。单层抽击，柔韧的皮革包裹着臀峰，带来火辣辣的灼痛；若将革带折叠，声音愈发清脆，痛感更强烈。",
    "sound": "抽击时，“啪”声响亮；折叠后，则是“啪嗒”的脆响。",
    "application": "用于体现绝对的权力关系，折叠后的威力较大，能迅速使受罚者出声哀叹，祈求轻饶。"
  }
}

{
  "name": "木制饭匙",
  "description": "庖厨中用于添饭的木勺，多为梨木或枣木所制。",
  "attributes": {
    "power_value": "3-5",
    "special_effects": [
      "圆印",
      "痛点集中",
      "居家羞耻"
    ],
    "tactile_sensation": "痛感集中短促。",
    "sound": "“梆、梆”之声，清脆而响亮。",
    "application": "家庭内部的即兴惩罚，带来的痛楚出人意料，适合制造一些带有生活气息的情节。"
  }
}

{
  "name": "马鞭",
  "description": "本为贵族策马之用，多以鞣制牛皮或编织丝线为杆，末梢缀以皮结或短穗。",
  "attributes": {
    "power_value": "5-7",
    "special_effects": [
      "身份压制",
      "鞭痕细长",
      "火辣灼痛"
    ],
    "tactile_sensation": "痛感清脆而火辣。细长的鞭身能将力道高度集中，在肌肤上留下一道道清晰的、火烧火燎的细长红痕。",
    "sound": "“嗖—啪”，破空之声轻快，落肉之声清脆响亮。",
    "application": "多用于氏族家庭的即兴惩戒，或带有征服意味的闺房训诫。",
    "corpus_example": ""
  }
}

{
  "name": "软皮鞭",
  "description": "选用上好小羊皮或鹿皮，精心鞣制裁剪而成，通体柔软，无柄，或仅有短小的皮质握柄。此物专为闺房之乐而生，其存在并非为了造成重创，而是为了制造痛与乐的交织。",
  "attributes": {
    "power_value": "3-5",
    "special_effects": [
      "闺房专属",
      "情趣羞耻",
      "覆盖性灼痛"
    ],
    "tactile_sensation": "痛感是大面积的、火辣辣的酥麻与灼痛。柔软的皮条覆盖在肌肤上，带来一种包裹性的痛感，很容易将肌肤打得通红发热，却极难造成破损。",
    "sound": "“噼啪”作响，带着皮革特有的拍击声。",
    "application": "专用于闺房调教与前戏，是夫妻间增加情趣的佳品。其物理伤害极低，但带来的感官刺激与羞耻感却极为强烈。"
  }
}

{
  "name": "牛筋鞭",
  "description": "取公牛背上最长最韧的筋脉，经盐水浸泡、桐油浸透、反复捶打晾晒而成。此乃家法与刑罚中的重器，轻易不动。",
  "attributes": {
    "power_value": "10-15",
    "special_effects": [
      "深度钝痛",
      "破防利器",
      "森冷鞭痕"
    ],
    "tactile_sensation": "痛感沉重且具有穿透力。每一鞭落下，都像是有一条烧红的铁棍狠狠地印在臀上，痛楚会瞬间穿透皮肉，直达筋骨。",
    "sound": "破空之声沉闷如风吼（“呜”），落肉之声则是“噗”的一声闷。",
    "application": "用于惩戒大过或进行刑讯。"
  }
}

{
  "name": "毛竹大板",
  "description": "选用整块毛竹，精工雕琢而成。其分量极重，板身厚实，表面打磨得光可鉴人。一旦动用，意味着犯下滔天大错。",
  "attributes": {
    "power_value": "15-20",
    "special_effects": [
      "臀浪",
      "深度钝痛",
      "持久酸胀",
      "冰冷触感"
    ],
    "tactile_sensation": "痛感沉重、猛烈，是足以撕碎心防的钝痛。",
    "sound": "“砰！”声如重锤，轰然作响，震人心魄。",
    "application": "用于重大过错或用于行刑。能对臀部造成严重的伤害。"
  }
}

{
  "name": "木板（透风板）",
  "description": "专为执行家法而造。极为坚固，恰好可以覆盖女子的两片臀瓣。一些板子上会开有数个孔洞，是为“透风板”，古人云可“引风入骨”，加剧痛楚。",
  "attributes": {
    "power_value": "7-10 (透风板: 8-12) (祭祀重板: 10-12)",
    "special_effects": [
      "明显板痕",
      "深度瘀伤",
      "权威象征"
    ],
    "tactile_sensation": "痛感沉重、猛烈。每一次击打，都能带来剧烈痛楚。",
    "sound": "“啪！”比女板声音更加深沉。若为透风板，则会伴有“呼”的风声。",
    "application": "家法中的主角，特别是透风板，其伤害足以让受罚者数日无法行动。"
  }
}
